// Themed menus (PLAN-FINAL 1.2): the serializable menu main sends to the overlay. Main builds entries with run
// closures, strips the closures into this spec (menu-host) and keeps them in its own registry; the overlay draws
// the spec and answers `menu.pick` with an opaque item id only. Pure module: no Electron, no DOM.
import { z } from 'zod'
import type { Platform } from './commands'

// ---- Limits ----

/** Item ids are generated by main; the overlay echoes them back unchanged. */
export const MENU_ITEM_ID_RE = /^[A-Za-z0-9._:-]{1,80}$/
export const MENU_LABEL_MAX = 200
export const MENU_TITLE_MAX = 2048
export const MENU_ACCEL_MAX = 64
/** Items per level (separators included), the bookmark bar's cap. */
export const MENU_LEVEL_MAX = 400
/** Levels including the root (the bookmark bar's "(Too deep)" cap). */
export const MENU_DEPTH_MAX = 8
/** Nodes in the whole tree, separators included. Bookmark menus over this end with "More in Bookmarks manager…". */
export const MENU_NODES_MAX = 5000

// ---- Types ----

export type MenuKind = 'page' | 'edit' | 'tab' | 'group' | 'bookmarks' | 'profiles'
export type MenuPlacement = 'point' | 'below'

export interface MenuItemNode {
  kind: 'item'
  id: string
  label: string
  /** Accelerator string for the overlay's shortcut chips (registry format, e.g. 'CmdOrCtrl+C'). */
  accel?: string
  enabled: boolean
  check?: 'check' | 'radio'
  checked?: boolean
  /** Tooltip (full bookmark title or URL when the label is truncated). */
  title?: string
  /** Present = this item opens a submenu and cannot be picked itself. */
  submenu?: MenuItemSpec[]
}
export interface MenuSeparator {
  kind: 'separator'
}
export type MenuItemSpec = MenuItemNode | MenuSeparator

/** Window-content coordinates; width/height 0 = a point. */
export interface MenuAnchor {
  x: number
  y: number
  width: number
  height: number
}

export interface MenuSpec {
  /** crypto.randomUUID() from main; `menu.pick`/`menu.dismiss` must echo it. */
  menuId: string
  kind: MenuKind
  /** Accessible name of the root menu ("Page", "Tab", "Bookmarks", ...). */
  label: string
  anchor: MenuAnchor
  /** Context menus at the pointer; button menus below the button. */
  placement: MenuPlacement
  /** Opened by keyboard: highlight the first enabled item. */
  focusFirst: boolean
  platform: Platform
  items: MenuItemSpec[]
}

// ---- Schemas ----

export const MenuKindSchema = z.enum(['page', 'edit', 'tab', 'group', 'bookmarks', 'profiles'])
export const MenuItemIdSchema = z.string().regex(MENU_ITEM_ID_RE)
export const MenuAnchorSchema = z.strictObject({
  x: z.number(),
  y: z.number(),
  width: z.number().nonnegative(),
  height: z.number().nonnegative()
})

const MenuSeparatorSchema = z.strictObject({ kind: z.literal('separator') })

const MenuItemNodeSchema: z.ZodType<MenuItemNode> = z.strictObject({
  kind: z.literal('item'),
  id: MenuItemIdSchema,
  label: z.string().max(MENU_LABEL_MAX),
  accel: z.string().max(MENU_ACCEL_MAX).optional(),
  enabled: z.boolean(),
  check: z.enum(['check', 'radio']).optional(),
  checked: z.boolean().optional(),
  title: z.string().max(MENU_TITLE_MAX).optional(),
  submenu: z.array(z.lazy(() => MenuItemSpecSchema)).max(MENU_LEVEL_MAX).optional()
})

export const MenuItemSpecSchema: z.ZodType<MenuItemSpec> = z.union([MenuItemNodeSchema, MenuSeparatorSchema])

export const MenuSpecSchema: z.ZodType<MenuSpec> = z
  .strictObject({
    menuId: z.string().uuid(),
    kind: MenuKindSchema,
    label: z.string().max(MENU_LABEL_MAX),
    anchor: MenuAnchorSchema,
    placement: z.enum(['point', 'below']),
    focusFirst: z.boolean(),
    platform: z.enum(['mac', 'win']),
    items: z.array(MenuItemSpecSchema).max(MENU_LEVEL_MAX)
  })
  .superRefine((m, ctx) => {
    if (menuDepth(m.items) > MENU_DEPTH_MAX) ctx.addIssue({ code: 'custom', message: `Menu is deeper than ${MENU_DEPTH_MAX} levels` })
    if (countNodes(m.items) > MENU_NODES_MAX) ctx.addIssue({ code: 'custom', message: `Menu has more than ${MENU_NODES_MAX} nodes` })
  })

// ---- Pure helpers ----

/** Levels of a tree: [] is 0, a flat list is 1, one submenu level is 2. */
export function menuDepth(items: readonly MenuItemSpec[]): number {
  let max = 0
  for (const it of items) {
    const d = it.kind === 'item' && it.submenu ? 1 + menuDepth(it.submenu) : 1
    if (d > max) max = d
  }
  return max
}

/** Every node in the tree, separators and submenu parents included. */
export function countNodes(items: readonly MenuItemSpec[]): number {
  let n = 0
  for (const it of items) {
    n++
    if (it.kind === 'item' && it.submenu) n += countNodes(it.submenu)
  }
  return n
}

/** Drops leading, trailing and repeated separators at every level (native menus do the same). */
export function trimSeparators(items: readonly MenuItemSpec[]): MenuItemSpec[] {
  const out: MenuItemSpec[] = []
  for (const it of items) {
    if (it.kind === 'separator') {
      if (out.length > 0 && out[out.length - 1]?.kind !== 'separator') out.push(it)
    } else {
      out.push(it.submenu ? { ...it, submenu: trimSeparators(it.submenu) } : it)
    }
  }
  if (out[out.length - 1]?.kind === 'separator') out.pop()
  return out
}

/** The item with this id anywhere in the tree (depth-first), or null. Separators have no id. */
export function findItem(items: readonly MenuItemSpec[], id: string): MenuItemNode | null {
  for (const it of items) {
    if (it.kind !== 'item') continue
    if (it.id === id) return it
    if (it.submenu) {
      const hit = findItem(it.submenu, id)
      if (hit) return hit
    }
  }
  return null
}

/**
 * A one-line menu label: whitespace runs (newlines, tabs) become one space, and anything longer than `max` UTF-16
 * units (the schema's measure) is cut with an ellipsis, never inside a surrogate pair. Callers put the full text in
 * `title`.
 */
export function truncateLabel(label: string, max = MENU_LABEL_MAX): string {
  const flat = label.replace(/\s+/g, ' ').trim()
  if (flat.length <= max) return flat
  let cut = Math.max(0, max - 1)
  const last = flat.charCodeAt(cut - 1)
  if (last >= 0xd800 && last <= 0xdbff) cut--
  return flat.slice(0, cut).trimEnd() + '…'
}
